// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { type ApplicationLimitsInput, FileView } from "../packages/app-backend/src/index.js";
import { appendFile, committedFile, fileJson, initiateFile } from "./backend-file-fixture.js";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

describe("finite application upload reservations and grants", () => {
  let fixture: BackendFixture | undefined;
  afterEach(async () => fixture?.close());
  async function setup(limits: ApplicationLimitsInput = {}) {
    fixture = await backendFixture({ limits });
    return { fixture, cookie: (await fixture.register()).cookie };
  }
  const input = (size: number) => ({ name: "bounded.txt", contentType: "text/plain", size });

  it("T-AC-56 atomically reserves whole declared sizes under concurrent requests", async () => {
    const { fixture, cookie } = await setup({ objectBytes: 8, storageBytes: 10 });
    const results = await Promise.all([
      fileJson(fixture, cookie, "/files", input(6)),
      fileJson(fixture, cookie, "/files", input(6)),
    ]);
    expect(results.filter((response) => response.status === 201)).toHaveLength(1);
    expect(
      results.filter((response) => response.status >= 400 && response.status < 500),
    ).toHaveLength(1);
    expect((await fileJson(fixture, cookie, "/files", input(5))).status).toBeGreaterThanOrEqual(
      400,
    );
    expect((await fileJson(fixture, cookie, "/files", input(4))).status).toBe(201);
  });

  it("T-AC-56 enforces per-object and object-count limits including pending uploads", async () => {
    const { fixture, cookie } = await setup({ objectBytes: 4, storageBytes: 32, maxFiles: 1 });
    expect((await fileJson(fixture, cookie, "/files", input(5))).status).toBe(413);
    expect((await fileJson(fixture, cookie, "/files", input(4))).status).toBe(201);
    expect((await fileJson(fixture, cookie, "/files", input(1))).status).toBeGreaterThanOrEqual(
      400,
    );
  });

  it("T-AC-56 refuses oversized streaming chunks without changing durable offset", async () => {
    const { fixture, cookie } = await setup({ objectBytes: 8, storageBytes: 16, chunkBytes: 3 });
    const initial = await initiateFile(fixture, cookie, new Uint8Array(6));
    const response = await appendFile(fixture, cookie, initial, new Uint8Array(4));
    expect(response.status).toBe(413);
    const retained = FileView.parse(
      await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
    );
    expect(retained.offset).toBe(0);
    expect((await readFile(join(fixture.filesRoot, initial.id))).byteLength).toBe(0);
  });

  it("T-AC-56 preserves finite reservations across a real runtime and database restart", async () => {
    const { fixture, cookie } = await setup({ objectBytes: 8, storageBytes: 8 });
    await initiateFile(fixture, cookie, new Uint8Array(8));
    await fixture.restart();
    const denied = await fileJson(fixture, cookie, "/files", input(1));
    expect(denied.status).toBeGreaterThanOrEqual(400);
    expect(denied.status).toBeLessThan(500);
  });

  it("T-AC-56 fences expired partial uploads without making their bytes available", async () => {
    const { fixture, cookie } = await setup({ uploadTtlMs: 1000 });
    const initial = await initiateFile(fixture, cookie, new Uint8Array(2));
    fixture.advance(1100);
    const append = await appendFile(fixture, cookie, initial, new Uint8Array(2));
    expect(append.status).toBeGreaterThanOrEqual(400);
    expect(append.status).toBeLessThan(500);
    expect(
      (await fixture.request(`/files/${initial.id}/download`, { headers: { cookie } })).status,
    ).toBeGreaterThanOrEqual(400);
  });

  it("T-AC-57 denies a session-bound download grant to a different user and after explicit revocation", async () => {
    const { fixture, cookie } = await setup();
    const { file } = await committedFile(fixture, cookie);
    const response = await fileJson(fixture, cookie, `/files/${file.id}/grants`, {
      expectedRevision: file.revision,
    });
    expect(response.status).toBe(201);
    const grant = (await response.json()) as { id: string; url: string };
    const path = new URL(grant.url, fixture.baseUrl).pathname.replace("/api/app/v1", "");
    const stranger = await fixture.register({
      name: "Stranger",
      email: "stranger@example.test",
      password: "Synthetic-stranger-passphrase-192!",
    });
    expect((await fixture.request(path, { headers: { cookie: stranger.cookie } })).status).toBe(
      404,
    );
    const revoke = await fixture.request(`/files/${file.id}/grants/${grant.id}`, {
      method: "DELETE",
      headers: { cookie, "content-type": "application/json", "idempotency-key": randomUUID() },
      body: "{}",
    });
    expect(revoke.status).toBe(200);
    expect((await fixture.request(path, { headers: { cookie } })).status).toBe(404);
  });

  it("T-AC-56 rejects mutable completion replay after a revision or digest changes", async () => {
    const { fixture, cookie } = await setup();
    const bytes = new TextEncoder().encode("abc");
    const initial = await initiateFile(fixture, cookie, bytes);
    const appended = FileView.parse(
      await (await appendFile(fixture, cookie, initial, bytes)).json(),
    );
    const key = randomUUID();
    const first = await fileJson(
      fixture,
      cookie,
      `/files/${initial.id}/complete`,
      { expectedRevision: appended.revision },
      key,
    );
    expect(first.status).toBe(200);
    const replay = await fileJson(
      fixture,
      cookie,
      `/files/${initial.id}/complete`,
      { expectedRevision: appended.revision },
      key,
    );
    expect(replay.status).toBe(200);
    expect(await replay.json()).toEqual(await first.json());
    const conflict = await fileJson(
      fixture,
      cookie,
      `/files/${initial.id}/complete`,
      { expectedRevision: appended.revision + 1 },
      key,
    );
    expect(conflict.status).toBe(409);
  });
});
